<!doctype html><html lang="lt"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MYGAME – paskola</title><link rel="stylesheet" href="assets/app.css"></head><body><div class="topbar"><div><b>MYGAME</b><span>Verslo simuliatorius</span></div><div class="topstats"><strong>🏦 Finansavimas</strong></div></div><main class="page loan-page"><div class="intro"><div><span class="eyebrow">ĮMONĖS FINANSAI</span><h1>Verslo paskola</h1><p>Pasirink banką, paskolos sumą ir terminą. Bankas automatiškai įvertins įmonės riziką.</p></div></div><?php if($notice): ?><div class="loan-alert good"><?= htmlspecialchars($notice) ?></div><?php endif; ?><?php if($error): ?><div class="loan-alert bad"><?= htmlspecialchars($error) ?></div><?php endif; ?><section class="loan-layout dashboard-loan-layout"><div class="card loan-form"><div class="card-head"><div><small>PARAIŠKA</small><strong><?= htmlspecialchars($company['name']??'Įmonė') ?></strong></div></div><form method="post"><label>Bankas<select name="bank_id" required><?php foreach($banks as $b): ?><option value="<?= (int)$b['id'] ?>"><?= htmlspecialchars($b['name']) ?> · <?= number_format((float)$b['min_amount'],0,',',' ') ?>–<?= number_format((float)$b['max_amount'],0,',',' ') ?> €</option><?php endforeach; ?></select></label><label>Paskolos suma<input name="amount" type="text" inputmode="decimal" value="25000" autocomplete="off" required></label><label>Terminas mėnesiais<input name="months" type="text" inputmode="numeric" value="60" autocomplete="off" required></label><input type="hidden" name="csrf" value="<?= htmlspecialchars($csrf) ?>"><input type="hidden" name="action" value="loan"><button class="start">Pateikti bankui <span>→</span></button></form></div><aside class="card loan-company"><small>ĮMONĖS SĄSKAITOS</small><h2><?= htmlspecialchars($company['name']??'') ?></h2><?php if(!$accounts): ?><div class="no-account"><b>Banko sąskaitos nėra</b><span>Prieš naudojantis banko paslaugomis įmonei reikia atidaryti sąskaitą.</span></div><?php endif; ?><?php foreach($banks as $b): $hasBankAccount=false; foreach($accounts as $a){if((int)$a['bank_id']===(int)$b['id']){$hasBankAccount=true;break;}} if(!$hasBankAccount): ?><form method="post" class="open-account-form"><input type="hidden" name="csrf" value="<?= htmlspecialchars($csrf) ?>"><input type="hidden" name="action" value="open_account"><input type="hidden" name="bank_id" value="<?= (int)$b['id'] ?>"><button type="submit">Atidaryti sąskaitą · <?= htmlspecialchars($b['name']) ?></button></form><?php endif; endforeach; ?><?php if($accounts): ?><div class="accounts-title">MANO SĄSKAITOS</div><?php foreach($accounts as $a): ?><div class="bank-account-box account-item"><small><?= $a['is_primary']?'PAGRINDINĖ · ':'' ?><?= htmlspecialchars($a['bank_name']) ?></small><b><?= htmlspecialchars(trim(chunk_split((string)$a['account_number'],4,' '))) ?></b><strong><?= number_format((float)$a['balance'],2,',',' ') ?> <?= htmlspecialchars($a['currency']) ?></strong><?php if(!$a['is_primary']): ?><form method="post"><input type="hidden" name="csrf" value="<?= htmlspecialchars($csrf) ?>"><input type="hidden" name="action" value="set_primary"><input type="hidden" name="account_id" value="<?= (int)$a['id'] ?>"><button class="mini-action">Nustatyti pagrindine</button></form><?php endif; ?></div><?php endforeach; ?><?php endif; ?><?php if($account): ?><div class="bank-account-box primary-summary"><small>PAGRINDINĖ SĄSKAITA · <?= htmlspecialchars($account['bank_name']??'') ?></small><b><?= htmlspecialchars(trim(chunk_split((string)($account['account_number']??''),4,' '))) ?></b><strong><?= number_format((float)($account['balance']??0),2,',',' ') ?> <?= htmlspecialchars($account['currency']??'EUR') ?></strong></div><?php endif; ?><div class="stats"><?php if($account): ?><div><span>Sąskaitos balansas</span><strong><?= number_format((float)($account['balance']??0),0,',',' ') ?> €</strong></div><?php endif; ?><div><span>Turtas</span><strong><?= number_format((float)($company['assets']??0),0,',',' ') ?> €</strong></div><div><span>Įsipareigojimai</span><strong><?= number_format((float)($company['liabilities']??0),0,',',' ') ?> €</strong></div><div><span>Mėn. pajamos</span><strong><?= number_format((float)($company['monthly_revenue']??0),0,',',' ') ?> €</strong></div><div><span>Mėn. pelnas</span><strong><?= number_format((float)($company['monthly_profit']??0),0,',',' ') ?> €</strong></div></div></aside></aside><aside class="card company-finance"><small>ĮMONĖS FINANSINĖ BŪKLĖ</small><div class="stats"><?php if($account): ?><div><span>Sąskaitos balansas</span><strong><?= number_format((float)($account['balance']??0),0,',',' ') ?> €</strong></div><?php endif; ?><div><span>Turtas</span><strong><?= number_format((float)($company['assets']??0),0,',',' ') ?> €</strong></div><div><span>Įsipareigojimai</span><strong><?= number_format((float)($company['liabilities']??0),0,',',' ') ?> €</strong></div><div><span>Mėn. pajamos</span><strong><?= number_format((float)($company['monthly_revenue']??0),0,',',' ') ?> €</strong></div><div><span>Mėn. pelnas</span><strong><?= number_format((float)($company['monthly_profit']??0),0,',',' ') ?> €</strong></div></div><div class="info-box"><b>Svarbu žinoti</b><span>• Paskola išmokama į pasirinkto banko sąskaitą.<br>• Įmokos mokamos pagal grafiką.<br>• 1 vėlavimo diena – be sankcijų.<br>• Nuo 2 dienos taikomi 0,05% delspinigiai.</span></div><?php if($offer): ?><aside class="card loan-result <?= $offer['approved']?'approved':'rejected' ?>"><small>BANKO SPRENDIMAS</small><h2><?= $offer['approved']?'Paskola patvirtinta':'Paraiška atmesta' ?></h2><p><?= htmlspecialchars($offer['reason']) ?></p><div class="offer-rate"><?= number_format((float)$offer['interest_rate'],2,',',' ') ?>%</div><div class="stats"><div><span>Rizikos balas</span><strong><?= number_format((float)$offer['risk_score'],1,',',' ') ?>/100</strong></div><div><span>Rizikos priedas</span><strong>+<?= number_format((float)$offer['risk_margin'],2,',',' ') ?>%</strong></div><div><span>Mėnesinė įmoka</span><strong><?= number_format((float)$offer['monthly_payment'],2,',',' ') ?> €</strong></div></div><?php if($offer['approved']): ?><form method="post" class="accept-loan-form"><input type="hidden" name="csrf" value="<?= htmlspecialchars($csrf) ?>"><input type="hidden" name="action" value="accept_loan"><input type="hidden" name="application_id" value="<?= (int)$offer['application_id'] ?>"><button class="start">Priimti paskolos pasiūlymą <span>→</span></button></form><?php endif; ?></aside><?php endif; ?></section><?php if($activeLoans): ?><section class="card finance-section active-loans-card"><div class="card-head"><div><small>AKTYVIOS PASKOLOS (<?= count($activeLoans) ?>)</small></div></div><?php foreach($activeLoans as $l): ?><div class="finance-row loan-summary-row"><span><b><?= htmlspecialchars($l['bank_name']) ?></b><small>Likutis <?= number_format((float)$l['outstanding_principal'],2,',',' ') ?> € · <?= number_format((float)$l['annual_interest_rate'],2,',',' ') ?>%</small></span><span class="loan-summary-metric"><small>Mėnesio įmoka</small><b><?= number_format((float)$l['monthly_payment'],2,',',' ') ?> €</b></span><span class="loan-summary-metric"><small>Kita įmoka</small><b><?= htmlspecialchars(substr((string)($l['actual_next_payment_at']??$l['next_payment_at']),0,10)) ?></b></span><i class="pay-status paid">Aktyvi</i></div><?php endforeach; ?></section><?php endif; ?><?php if($activeLoans): ?><section class="repayment-grid"><div class="card schedule-card"><div class="card-head"><div><small>PASKOLOS GRAFIKAS</small><strong>Mokėjimų grafikas</strong></div></div><?php foreach($activeLoans as $loan): $rows=$loanSchedules[(int)$loan['id']]??[]; ?><div class="schedule-loan-title"><?= htmlspecialchars($loan['bank_name']) ?> · likutis <?= number_format((float)$loan['outstanding_principal'],2,',',' ') ?> €</div><div class="schedule-table"><div class="schedule-row schedule-header"><span>#</span><span>Data</span><span>Įmoka</span><span>Palūkanos</span><span>Paskolos suma</span><span>Būsena</span></div><?php foreach(array_slice($rows,0,5) as $p): ?><div class="schedule-row"><span><?= (int)$p['installment_no'] ?></span><span><?= htmlspecialchars(substr((string)$p['due_at'],0,10)) ?></span><span><?= number_format((float)$p['scheduled_amount']+(float)$p['penalty_amount'],2,',',' ') ?> €</span><span><?= number_format((float)$p['interest_amount'],2,',',' ') ?> €</span><span><?= number_format((float)$p['principal_amount'],2,',',' ') ?> €</span><span><i class="pay-status <?= htmlspecialchars($p['status']) ?>"><?= $p['status']==='paid'?'Sumokėta':($p['status']==='late'?'Vėluoja':($p['status']==='due'?'1 d. vėlavimas':'Laukiama')) ?></i><?php if($p['status']!=='paid' && ((int)$p['installment_no']===(int)($rows[0]['installment_no']??0))): ?><form method="post" class="pay-form"><input type="hidden" name="csrf" value="<?= htmlspecialchars($csrf) ?>"><input type="hidden" name="action" value="pay_installment"><input type="hidden" name="payment_id" value="<?= (int)$p['id'] ?>"><button class="mini-action">Mokėti</button></form><?php endif; ?><?php if((float)$p['penalty_amount']>0): ?><small class="penalty">+<?= number_format((float)$p['penalty_amount'],2,',',' ') ?> € delsp.</small><?php endif; ?></span></div><?php endforeach; ?></div><?php endforeach; ?></div><div class="card late-policy"><small>VĖLAVIMO POLITIKA</small><h3>Įmokų vėlavimas</h3><ul><li><b>1 diena</b> – sankcijų netaikome.</li><li><b>Nuo 2 dienos</b> – 0,05% delspinigiai nuo nesumokėtos įmokos už kiekvieną papildomą dieną.</li><li>Delspinigiai automatiškai pridedami prie mokėtinos sumos ir rodomi grafike.</li><li>Vėliau galėsime kredito reitingą susieti su pasikartojančiais vėlavimais.</li></ul></div></section><?php endif; ?><?php if($transactions): ?><section class="card finance-section"><div class="card-head"><div><small>SĄSKAITA</small><strong>Paskutinės operacijos · <?= htmlspecialchars($account['bank_name']??'') ?></strong></div></div><?php foreach($transactions as $t): ?><div class="finance-row"><span><?= htmlspecialchars($t['description']) ?><small><?= htmlspecialchars((string)($t['game_date']??substr((string)$t['created_at'],0,10))) ?></small></span><b class="<?= (float)$t['amount']>=0?'positive':'negative' ?>"><?= (float)$t['amount']>=0?'+':'' ?><?= number_format((float)$t['amount'],2,',',' ') ?> €</b></div><?php endforeach; ?></section><?php endif; ?></main></main></body></html>